-- PT119-S3-Q10. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT119-S3-Q10$batch06$ AND q.stimulus=$batch06$Fred argued that, since Kathleen is a successful film director, she has probably worked with famous actors. But, while Fred is right in supposing that most successful film directors work with famous actors, his conclusion is not warranted. For, as he knows, Kathleen works only on documentary films, and directors of documentaries rarely work with famous actors.$batch06$ AND q.prompt=$batch06$Which one of the following strategies is used above to criticize Fred's reasoning?$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT119-S3-Q10$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT119-S3-Q10$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$Fred's conclusion that Kathleen has probably worked with famous actors is not warranted.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Fred knows Kathleen directs only documentaries, and documentary directors rarely work with famous actors.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The author agrees with Fred's general rule: most successful directors work with famous actors. The problem is that Fred knew something more specific about Kathleen that points the other way. When you know a person belongs to a group where the rule does not hold, the general rule stops being good evidence about them.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Fred failed to take relevant information into account.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT119-S3-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The author says plenty is known about Kathleen: that she makes documentaries. That is what defeats Fred's conclusion.$batch06$), ($batch06$B$batch06$, $batch06$The author shows Fred's conclusion is unwarranted, not that it is false. "Rarely" leaves room for Kathleen to have worked with famous actors.$batch06$), ($batch06$C$batch06$, $batch06$The relevant information is that Kathleen makes documentaries. Fred knew it and ignored it.$batch06$), ($batch06$D$batch06$, $batch06$This is the most popular wrong answer, chosen by about one student in five. But the author explicitly says Fred is right that *most* directors work with famous actors. Fred never assumed *all* do, and the author does not accuse him of it. The problem is not the rule. It is applying it to someone in a known exception group.$batch06$), ($batch06$E$batch06$, $batch06$The author grants Fred's claim about most directors. They do not say he failed to show it.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT119-S3-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
